values ($lx$wiser-counseling-anna-liu-scottsdale$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Wiser Counseling (Anna Liu, LCSW)$lx$, null, $lx$Scottsdale therapy practice led by Mandarin-speaking clinical social worker Anna Liu, focusing on relationships and couples.$lx$, $lx$斯科茨代爾心理諮商診所，由會說國語的臨床社工師 Anna Liu 主持，專長人際關係及伴侶諮商。$lx$, $lx$Wiser Counseling is a therapy practice at 9160 E Bahia Dr, Suite 107, in Scottsdale, led by Anna Liu, a licensed clinical social worker (Arizona license 16803). The profile lists relationship issues, women's issues and marital and premarital counseling as the main focus, and Liu works with adults as individuals and couples, using approaches that include acceptance and commitment therapy, attachment-based, Buddhism-based and compassion-focused therapy and CBT. Liu lists $195 per session and is out of network, with claims filed through Reimbursify. Liu speaks English and Mandarin. Languages as listed on this therapist's Psychology Today profile, checked November 2026.$lx$, $lx$Wiser Counseling 是位於斯科茨代爾（Scottsdale）9160 E Bahia Dr, Suite 107 的心理諮商診所，由亞利桑那州執照臨床社工師 Anna Liu（執照號碼 16803）主持。個人頁面列出主要專長為人際關係、女性議題及婚姻與婚前諮商，服務成人個人及伴侶，採用接納與承諾治療、依附取向、佛學取向、慈悲焦點治療及認知行為治療等方法。每次諮商費用列為 195 美元，不在保險網絡內，可透過 Reimbursify 申請理賠。能說英語及國語。語言資訊依據其 Psychology Today 個人頁面，2026 年 11 月查核。$lx$, $lx$Scottsdale$lx$, $lx$Greater Phoenix$lx$, $lx$9160 E Bahia Dr, Suite 107, Scottsdale, AZ 85260$lx$, null, null, null, $lx$https://www.psychologytoday.com/us/therapists/wiser-counseling-anna-liu-scottsdale-az/749949$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Wiser Counseling (Anna Liu, LCSW)$lx$, $lx$Scottsdale$lx$, $lx$medical$lx$, $lx$psychologytoday.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$therapist counselor mental health$lx$, $lx$心理諮商 心理治療$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
